// Estrae il messaggio utente dal payload del webhook di Meta.
// Gli aggiornamenti di stato (sent/delivered/read) escono con valido=false.
const body = $json.body || {};
const change = ((body.entry || [])[0]?.changes || [])[0]?.value || {};
const msg = (change.messages || [])[0];
if (!msg) return [{ json: { valido: false } }];

const contatto = (change.contacts || [])[0] || {};
let testo = '';
let bottone = '';

if (msg.type === 'text') {
  testo = (msg.text?.body || '').trim();
} else if (msg.type === 'interactive') {
  const i = msg.interactive || {};
  if (i.type === 'button_reply') { bottone = i.button_reply.id; testo = i.button_reply.title; }
  if (i.type === 'list_reply')   { bottone = i.list_reply.id;   testo = i.list_reply.title; }
} else if (msg.type === 'button') {
  bottone = msg.button?.payload || '';
  testo = msg.button?.text || '';
}

return [{ json: {
  valido: true,
  waId: msg.from,
  nome: contatto.profile?.name || '',
  tipo: msg.type,
  testo,
  bottone,
  msgId: msg.id,
} }];

// ═══ Cervello del bot: macchina a stati ═══
// Stati sessione: menu | galenica_attesa | prenota_tipo | prenota_slot | umano
const TZ = 'Europe/Rome';
const msgIn = $('Estrai messaggio').first().json;

// Testi fissi — ADATTA GLI ORARI a quelli reali della parafarmacia
const ORARI_TESTO = 'Lun–Ven 9:00–13:00 e 16:00–20:00 · Sab 9:00–13:00';
const INFO = '🕒 *Orari*\n' + ORARI_TESTO + '\n\n' +
  '📍 Via Silvio Vardabasso 1/a, Sassari\n' +
  '📞 079 278245\n' +
  '✉️ clienti@parafarmaciasassari.it\n\n' +
  'Per analisi e consulenze non serve appuntamento: puoi passare quando vuoi. ' +
  'Se preferisci un orario riservato, scrivi *menu* e scegli 📅 Prenota.';

// Sessione salvata (foglio "Sessioni")
const righe = $('Leggi sessione').all().map(i => i.json).filter(r => r && r.wa_id);
const sess = righe.length ? righe[righe.length - 1] : null;
let stato = sess?.stato || 'menu';
let dati = {};
try { dati = sess?.dati ? JSON.parse(sess.dati) : {}; } catch (e) { dati = {}; }

const testo = (msgIn.testo || '').toLowerCase().trim();
const scelta = msgIn.bottone || '';

const risposte = [];
const out = {
  azione: 'nessuna',
  dettagli: {},
  risposte,
  nuovaSessione: { stato: 'menu', dati: {} },
};

const aUtente = (payload) => risposte.push({ to: msgIn.waId, payload });
const testoWa = (t) => ({ type: 'text', text: { body: t, preview_url: false } });

function avvisaTitolare(tipo, dettaglio) {
  const OWNER = $env.TITOLARE_WA_ID;
  if (!OWNER) return;
  const TEMPLATE = $env.META_TEMPLATE_NOTIFICA;
  if (TEMPLATE) {
    // Template approvato: funziona anche fuori dalla finestra delle 24 ore
    risposte.push({ to: OWNER, payload: { type: 'template', template: {
      name: TEMPLATE, language: { code: 'it' },
      components: [{ type: 'body', parameters: [
        { type: 'text', text: tipo }, { type: 'text', text: dettaglio },
      ]}],
    }}});
  } else {
    // Testo libero: arriva solo se il titolare ha scritto al bot nelle ultime 24h
    risposte.push({ to: OWNER, payload: testoWa('🔔 ' + tipo + '\n' + dettaglio) });
  }
}

const MENU = {
  type: 'interactive',
  interactive: {
    type: 'list',
    header: { type: 'text', text: 'ArilùFarma · Assistente' },
    body: { text: 'Ciao' + (msgIn.nome ? ' ' + msgIn.nome.split(' ')[0] : '') + '! 👋 Sono l\u2019assistente virtuale di ArilùFarma. Come posso aiutarti?' },
    footer: { text: 'Scrivi "menu" in qualsiasi momento per tornare qui.' },
    action: { button: 'Scegli un servizio', sections: [{ title: 'Servizi', rows: [
      { id: 'galenica',  title: '🧪 Preparato galenico', description: 'Richiedi un preparato su misura' },
      { id: 'prenota',   title: '📅 Prenota',            description: 'Analisi o consulenza in sede' },
      { id: 'info',      title: '🕒 Orari e contatti',   description: 'Dove siamo e quando' },
      { id: 'operatore', title: '👤 Parla con noi',      description: 'Ti risponde il Dott. Conti' },
    ]}]},
  },
};

const SALUTI = ['ciao', 'salve', 'buongiorno', 'buonasera', 'menu', 'start', 'annulla', 'indietro'];

// ── Modalità "umano": il bot tace per 24h dopo il passaggio a operatore ──
if (stato === 'umano') {
  const da = dati.da ? DateTime.fromISO(dati.da) : DateTime.now().minus({ days: 2 });
  const attiva = DateTime.now().diff(da, 'hours').hours < 24;
  if (attiva && testo !== 'menu') {
    // Silenzio: la conversazione è in mano al Dott. Conti
    out.nuovaSessione = { stato: 'umano', dati };
    return [{ json: out }];
  }
  stato = 'menu';
}

// ── Comandi di reset ──
if (SALUTI.includes(testo) && !scelta) {
  aUtente(MENU);
  out.nuovaSessione = { stato: 'menu', dati: {} };
  return [{ json: out }];
}

// ── Scelte dal menu principale ──
if (scelta === 'galenica') {
  aUtente(testoWa('🧪 *Preparato galenico su misura*\n\nScrivimi in un unico messaggio di cosa hai bisogno: il preparato (o la ricetta), il dosaggio se lo conosci e per chi è.\n\nPasso tutto al Dott. Conti, che ti conferma la proposta entro 24 ore.'));
  out.nuovaSessione = { stato: 'galenica_attesa', dati: {} };
  return [{ json: out }];
}

if (scelta === 'prenota') {
  aUtente({ type: 'interactive', interactive: {
    type: 'button',
    body: { text: '📅 Perfetto! Cosa vuoi prenotare?' },
    action: { buttons: [
      { type: 'reply', reply: { id: 'tipo_analisi',    title: 'Analisi' } },
      { type: 'reply', reply: { id: 'tipo_consulenza', title: 'Consulenza' } },
    ]},
  }});
  out.nuovaSessione = { stato: 'prenota_tipo', dati: {} };
  return [{ json: out }];
}

if (scelta === 'info') {
  aUtente(testoWa(INFO));
  out.nuovaSessione = { stato: 'menu', dati: {} };
  return [{ json: out }];
}

if (scelta === 'operatore') {
  aUtente(testoWa('👤 Ho avvisato il Dott. Conti: ti risponderà qui su WhatsApp appena possibile.\n\nNel frattempo scrivi pure la tua domanda. Per tornare all\u2019assistente automatico scrivi *menu*.'));
  avvisaTitolare('Richiesta di contatto', (msgIn.nome || 'Un cliente') + ' (+' + msgIn.waId + ') vuole parlare con te su WhatsApp.');
  out.nuovaSessione = { stato: 'umano', dati: { da: DateTime.now().setZone(TZ).toISO() } };
  return [{ json: out }];
}

// ── Stato: attesa descrizione galenica ──
if (stato === 'galenica_attesa') {
  if (msgIn.tipo !== 'text' || !msgIn.testo) {
    aUtente(testoWa('Scrivimi due righe di testo con la tua richiesta, così la passo al Dott. Conti. 🙏'));
    out.nuovaSessione = { stato: 'galenica_attesa', dati: {} };
    return [{ json: out }];
  }
  out.azione = 'salva_richiesta';
  out.dettagli = { descrizione: msgIn.testo, nome: msgIn.nome, waId: msgIn.waId };
  aUtente(testoWa('✅ Richiesta ricevuta! Il Dott. Conti la sta già guardando: ti risponde qui su WhatsApp entro 24 ore con la proposta.\n\nScrivi *menu* se ti serve altro.'));
  avvisaTitolare('Nuova richiesta galenica', (msgIn.nome || 'Cliente') + ' (+' + msgIn.waId + '): ' + msgIn.testo.slice(0, 300));
  out.nuovaSessione = { stato: 'menu', dati: {} };
  return [{ json: out }];
}

// ── Stato: scelta del tipo di prenotazione ──
if (stato === 'prenota_tipo') {
  if (scelta === 'tipo_analisi' || scelta === 'tipo_consulenza') {
    const tipo = scelta === 'tipo_analisi' ? 'Analisi' : 'Consulenza';
    const ora = DateTime.now().setZone(TZ);
    out.azione = 'proponi_slot';
    out.dettagli = { tipo, finestra: {
      da: ora.toUTC().toISO(),
      a: ora.plus({ days: 7 }).endOf('day').toUTC().toISO(),
    }};
    out.nuovaSessione = { stato: 'prenota_slot', dati: { tipo } };
    return [{ json: out }];
  }
  aUtente(testoWa('Usa i pulsanti qui sopra per scegliere 😊 Oppure scrivi *menu* per ricominciare.'));
  out.nuovaSessione = { stato: 'prenota_tipo', dati: {} };
  return [{ json: out }];
}

// ── Stato: scelta dello slot ──
if (stato === 'prenota_slot') {
  if (scelta.startsWith('slot_')) {
    const inizio = DateTime.fromISO(scelta.slice(5), { zone: TZ });
    const fine = inizio.plus({ minutes: 30 });
    const tipo = dati.tipo || 'Appuntamento';
    const quando = inizio.setLocale('it').toFormat("cccc d LLLL 'alle' HH:mm");
    out.azione = 'crea_prenotazione';
    out.dettagli = {
      tipo,
      nome: msgIn.nome || 'Cliente WhatsApp',
      waId: msgIn.waId,
      inizio: inizio.toISO(),
      fine: fine.toISO(),
      quando,
    };
    aUtente(testoWa('Fatto ✅ *' + tipo + '* fissata per *' + quando + '* con il Dott. Conti.\n\n📍 Via Silvio Vardabasso 1/a, Sassari\n\nSe devi spostarla o disdirla, scrivici qui. A presto!'));
    avvisaTitolare('Nuova prenotazione', tipo + ' · ' + quando + ' · ' + (msgIn.nome || 'Cliente') + ' (+' + msgIn.waId + ')');
    out.nuovaSessione = { stato: 'menu', dati: {} };
    return [{ json: out }];
  }
  aUtente(testoWa('Scegli un orario dalla lista qui sopra, oppure scrivi *menu* per ricominciare.'));
  out.nuovaSessione = { stato: 'prenota_slot', dati };
  return [{ json: out }];
}

// ── Fallback: non ho capito → menu ──
aUtente(testoWa('Non sono sicuro di aver capito 🤔 Ecco cosa posso fare per te:'));
aUtente(MENU);
out.nuovaSessione = { stato: 'menu', dati: {} };
return [{ json: out }];

// Calcola gli slot liberi incrociando gli orari di apertura con l'agenda.
// ADATTA "ORARI" agli orari reali della parafarmacia (weekday: 1=lun … 7=dom).
const TZ = 'Europe/Rome';
const ORARI = {
  1: [[9, 0, 13, 0], [16, 0, 20, 0]],
  2: [[9, 0, 13, 0], [16, 0, 20, 0]],
  3: [[9, 0, 13, 0], [16, 0, 20, 0]],
  4: [[9, 0, 13, 0], [16, 0, 20, 0]],
  5: [[9, 0, 13, 0], [16, 0, 20, 0]],
  6: [[9, 0, 13, 0]],
  7: [],
};
const DURATA_MIN = 30;      // durata di ogni appuntamento
const MAX_SLOT = 9;         // massimo 10 righe in una lista WhatsApp
const MAX_PER_GIORNO = 3;   // per proporre più giorni diversi

const cervello = $('Cervello del bot').first().json;
const tipo = cervello.dettagli.tipo || 'Appuntamento';

// La risposta dell'API Calendar è un item con { items: [...] }
const eventi = $input.all().flatMap(i => i.json.items || []);
const occupati = eventi
  .filter(e => e.status !== 'cancelled')
  .map(e => ({
    da: DateTime.fromISO(e.start?.dateTime || (e.start?.date + 'T00:00:00'), { zone: TZ }),
    a:  DateTime.fromISO(e.end?.dateTime   || (e.end?.date   + 'T00:00:00'), { zone: TZ }),
  }));

const slots = [];
const oggi = DateTime.now().setZone(TZ).startOf('day');
for (let d = 1; d <= 7 && slots.length < MAX_SLOT; d++) {
  const g = oggi.plus({ days: d });
  let delGiorno = 0;
  for (const [h1, m1, h2, m2] of (ORARI[g.weekday] || [])) {
    let t = g.set({ hour: h1, minute: m1 });
    const chiusura = g.set({ hour: h2, minute: m2 });
    while (t.plus({ minutes: DURATA_MIN }) <= chiusura && slots.length < MAX_SLOT && delGiorno < MAX_PER_GIORNO) {
      const tFine = t.plus({ minutes: DURATA_MIN });
      const libero = !occupati.some(o => t < o.a && tFine > o.da);
      if (libero) { slots.push(t); delGiorno++; }
      t = tFine;
    }
  }
}

const waId = $('Estrai messaggio').first().json.waId;
const risposte = [];

if (!slots.length) {
  risposte.push({ to: waId, payload: { type: 'text', text: {
    body: 'In questi giorni l\u2019agenda è piena 😔 Scrivici qui la tua disponibilità e ti ricontattiamo noi, oppure passa in sede senza appuntamento.',
    preview_url: false,
  }}});
  return [{ json: { azione: 'nessuna', risposte, nuovaSessione: { stato: 'menu', dati: {} } } }];
}

risposte.push({ to: waId, payload: { type: 'interactive', interactive: {
  type: 'list',
  header: { type: 'text', text: 'Orari disponibili' },
  body: { text: '📅 Ecco i primi orari liberi per la tua *' + tipo.toLowerCase() + '*. Scegli quello che preferisci:' },
  footer: { text: 'Scrivi "menu" per annullare.' },
  action: { button: 'Vedi gli orari', sections: [{ title: tipo, rows: slots.map(t => ({
    id: 'slot_' + t.toISO({ suppressMilliseconds: true, includeOffset: false }),
    title: t.setLocale('it').toFormat('ccc d LLL · HH:mm'),
    description: tipo + ' · 30 minuti',
  }))}]},
}}});

return [{ json: { azione: 'nessuna', risposte, nuovaSessione: cervello.nuovaSessione } }];

// Trasforma l'array "risposte" in un item per ogni messaggio da inviare.
const cervello = $('Cervello del bot').first().json;
const sorgente = ($json && Array.isArray($json.risposte)) ? $json : cervello;
const nuovaSessione = sorgente.nuovaSessione || cervello.nuovaSessione || { stato: 'menu', dati: {} };
return (sorgente.risposte || []).map(r => ({ json: {
  to: r.to,
  payload: r.payload,
  statoSessione: nuovaSessione.stato,
  datiSessione: JSON.stringify(nuovaSessione.dati || {}),
} }));
